INSERT INTO "sensor_tags" ("id", "asset_id", "tag", "description", "eng_unit", "alert_low", "alert_high", "alert_high_tightened", "source_dataset", "source_signal", "transform", "origin") VALUES
  ('6e6a8f02-44d0-59cf-b6b1-e388f14700d4', '262d0095-f147-5d0c-bf94-0a10837459e1', 'P101_DE_VIB_RMS', 'P-101 drive-end vibration, RMS', 'mm/s', NULL, 4.5, 3.5, 'NASA IMS bearing test 2', 'bearing 1, channel 1', '{"mapping": "S1: mean of ~4.1 snapshots per replay hour x 36.29 (healthy median -> 2.8 mm/s). S2: first 100 healthy hours repeated.", "health_models": [{"asset": "P-101", "driver_tag": "P101_DE_VIB_RMS", "mode": "rising", "x_healthy": 2.8, "x_fail": 11.2, "smoothing": {"method": "rolling_median", "window_hours": 6}, "anchor_note": "2.8, 4.5, 7.1 and 11.2 mm/s are the zone boundaries commonly used for vibration severity (ISO 10816-3 style). Used here as illustrative anchors."}]}', 'public_proxy'),
  ('dfaae2d7-5be3-5700-bcf7-3c293a81dd6d', '262d0095-f147-5d0c-bf94-0a10837459e1', 'P101_DE_VIB_KURT', 'P-101 drive-end vibration, kurtosis', '-', NULL, 6.0, NULL, 'NASA IMS bearing test 2', 'bearing 1, channel 1', '{"mapping": "hourly mean, unscaled"}', 'public_proxy'),
  ('55c2d77b-88d2-5f9e-9ee5-d0ac3ab14322', '262d0095-f147-5d0c-bf94-0a10837459e1', 'P101_BRG_TEMP', 'P-101 drive-end bearing temperature', 'degC', NULL, 72.0, NULL, 'derived from P101_DE_VIB_RMS', 'none', '{"mapping": "58 + 2.2 x max(0, vib - 2.8), first-order lag tau 3 h, N(0, 0.3) noise, seed 100"}', 'synthetic'),
  ('3d33a3ac-c104-59b1-b18d-41453575b03b', 'dfe0c337-fe85-559b-96b0-98eded427720', 'P101B_DE_VIB_RMS', 'P-101B drive-end vibration, RMS', 'mm/s', NULL, 4.5, NULL, 'NASA IMS bearing test 2', 'bearing 4, channel 4', '{"mapping": "hourly mean x 36.12 (healthy median -> 2.0 mm/s); first 100 healthy hours repeated in both scenarios, because the rig''s shared shaft couples the failing bearing into bearing 4", "health_models": [{"asset": "P-101B", "driver_tag": "P101B_DE_VIB_RMS", "mode": "rising", "x_healthy": 2.0, "x_fail": 11.2, "smoothing": {"method": "rolling_median", "window_hours": 6}}]}', 'public_proxy'),
  ('7145ee44-1338-5af7-b3c1-2d5d5e986c50', '0508d44f-27af-5d7f-8c29-60b9ba5cb124', 'FI201_REFLUX_FLOW', 'Reflux flow to C-200', 'm3/h', 18.0, 22.0, NULL, 'Tennessee Eastman Process', 'XMEAS(14) separator underflow', '{"mapping": "20.0 + (x - normal mean) x 0.8; 4 samples (12 min) averaged per replay hour", "health_models": [{"asset": "FV-201", "driver_tag": "FI201_REFLUX_FLOW", "mode": "abs_deviation", "centre": 20.0, "x_healthy": 0.0, "x_fail": 8.0, "smoothing": {"method": "rolling_median", "window_hours": 6}}]}', 'public_proxy'),
  ('d836c5d8-0c36-59b6-9611-ec2765b9f331', '09ad774c-0073-5e12-8cf4-2a7b74375816', 'LI201_V201_LEVEL', 'Reflux drum level', '%', 25.0, 75.0, NULL, 'Tennessee Eastman Process', 'XMEAS(12) separator level', '{"mapping": "50.0 + (x - normal mean) x 1.0; 4 samples (12 min) averaged per replay hour", "health_models": [{"asset": "V-201", "driver_tag": "LI201_V201_LEVEL", "mode": "abs_deviation", "centre": 50.0, "x_healthy": 0.0, "x_fail": 30.0, "smoothing": {"method": "rolling_median", "window_hours": 6}}]}', 'public_proxy'),
  ('a5bb1622-a68c-5e88-a9c4-d3c678270838', 'b28d9db3-bf05-5303-aa35-c69543384450', 'PI201_V201_PRESS', 'Reflux drum pressure', 'barg', NULL, 2.3, NULL, 'Tennessee Eastman Process', 'XMEAS(13) separator pressure', '{"mapping": "1.8 + (x - normal mean) x 0.01; 4 samples (12 min) averaged per replay hour"}', 'public_proxy'),
  ('ed87bf1b-f2a8-524e-8033-4234f189e84e', 'fb7e457d-1a64-5a79-a007-dd8b113db8c7', 'TI301_CW_OUT', 'E-301 cooling-water outlet temperature', 'degC', NULL, 40.0, NULL, 'Tennessee Eastman Process', 'XMEAS(22) separator cooling-water outlet temperature', '{"mapping": "35.0 + (x - normal mean) x 2.0; 4 samples (12 min) averaged per replay hour"}', 'public_proxy'),
  ('f358ae5c-1b8d-52b1-9b46-997fb7a871c3', '66d0023d-1501-5f71-9d52-099fd264af55', 'TV301_POS', 'TV-301 valve position', '%', NULL, 80.0, NULL, 'Tennessee Eastman Process', 'XMV(11) condenser cooling-water flow', '{"mapping": "55.0 + (x - normal mean) x 4.0; 4 samples (12 min) averaged per replay hour", "health_models": [{"asset": "E-301", "driver_tag": "TV301_POS", "mode": "rising", "x_healthy": 55.0, "x_fail": 90.0, "smoothing": {"method": "rolling_median", "window_hours": 6}, "anchor_note": "Cooling margin: the further TV-301 must open to hold condensate temperature, the less spare cooling E-301 has. 90% open is treated as no margin."}, {"asset": "TV-301", "driver_tag": "TV301_POS", "mode": "rising", "x_healthy": 70.0, "x_fail": 95.0, "smoothing": {"method": "rolling_median", "window_hours": 6}, "anchor_note": "Valve travel margin. The valve itself stays healthy in both scenarios."}]}', 'public_proxy')
